import { GENERATED_PHOTOS } from './photos.generated'

/**
 * Photography wall data.
 *
 * The mechanical half of each entry — id, the two image paths, and the measured
 * aspect ratio — is generated by `npm run photos` into photos.generated.js.
 * The half a person writes lives here, keyed by the same id, so re-running the
 * script never overwrites a caption.
 *
 * An id is the source filename without its extension:
 * src/assets/photography/img4.webp is `img4`.
 */
/*
 * Optional, and empty until someone writes one. A photo with no entry here
 * simply shows no caption rather than falling back to its filename, which is
 * what the wall would otherwise put under a photograph.
 *
 *   img4: { caption: 'Low tide', location: 'Donegal', year: 2024 },
 */
const META = {}

export const PHOTOS = GENERATED_PHOTOS.map((photo) => ({ ...photo, ...META[photo.id] }))
